-- oracle: pub400
-- OLAP specifications: ranking, distribution, offsets, values, aggregates over windows and frames; one in WHERE refused.
CREATE TABLE {lib}.Q3T (ID INTEGER NOT NULL, GRP CHAR(1), V DECIMAL(7,2), D DATE, S VARCHAR(20));
INSERT INTO {lib}.Q3T VALUES (1,'A',10.50,'2024-01-15','apple'),(2,'A',20.00,'2024-02-29','banana'),(3,'B',NULL,'2023-12-31','cherry'),(4,'B',5.25,'2024-03-01',NULL),(5,'C',7.00,NULL,'date'),(6,NULL,1.00,'2024-01-01','fig');
SELECT ID, ROW_NUMBER() OVER (ORDER BY ID DESC) RN FROM {lib}.Q3T ORDER BY ID;
SELECT ID, GRP, ROW_NUMBER() OVER (PARTITION BY GRP ORDER BY ID) RN, RANK() OVER (ORDER BY GRP) RK, DENSE_RANK() OVER (ORDER BY GRP) DR FROM {lib}.Q3T ORDER BY ID;
SELECT ID, NTILE(4) OVER (ORDER BY ID) NT, PERCENT_RANK() OVER (ORDER BY ID) PR, CUME_DIST() OVER (ORDER BY ID) CD FROM {lib}.Q3T ORDER BY ID;
SELECT ID, LAG(ID) OVER (ORDER BY ID) L1, LAG(ID, 2, -1) OVER (ORDER BY ID) L2, LEAD(V) OVER (ORDER BY ID) LD FROM {lib}.Q3T ORDER BY ID;
SELECT ID, LAG(V) IGNORE NULLS OVER (ORDER BY ID) FROM {lib}.Q3T ORDER BY ID;
SELECT ID, FIRST_VALUE(ID) OVER (PARTITION BY GRP ORDER BY ID) FV, LAST_VALUE(ID) OVER (PARTITION BY GRP ORDER BY ID) LV, LAST_VALUE(ID) OVER (PARTITION BY GRP ORDER BY ID ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) LV2 FROM {lib}.Q3T ORDER BY ID;
SELECT ID, NTH_VALUE(ID, 2) OVER (ORDER BY ID ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) NV FROM {lib}.Q3T ORDER BY ID;
SELECT ID, SUM(V) OVER (ORDER BY ID ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING) S3, AVG(V) OVER (PARTITION BY GRP) A, COUNT(*) OVER () C FROM {lib}.Q3T ORDER BY ID;
SELECT ID, SUM(ID) OVER (ORDER BY ID RANGE BETWEEN 1 PRECEDING AND CURRENT ROW) R FROM {lib}.Q3T ORDER BY ID;
SELECT ID, SUM(ID) OVER (ORDER BY ID) CUM, MAX(ID) OVER (ORDER BY ID ROWS 2 PRECEDING) M FROM {lib}.Q3T ORDER BY ID;
SELECT ID, RATIO_TO_REPORT(ID) OVER () FROM {lib}.Q3T ORDER BY ID;
SELECT GRP, SUM(ID), RANK() OVER (ORDER BY SUM(ID) DESC) FROM {lib}.Q3T GROUP BY GRP ORDER BY 3;
SELECT ID FROM {lib}.Q3T ORDER BY ROW_NUMBER() OVER (ORDER BY ID DESC) FETCH FIRST 2 ROWS ONLY;
SELECT ID FROM {lib}.Q3T WHERE ROW_NUMBER() OVER (ORDER BY ID) = 1;
DROP TABLE {lib}.Q3T;
